<?php namespace Workspace; $pid=$project; ?>
<section class="panel"><h2>Сайты EngineLite</h2><p>Локальные установки 1.6.0. Публикация выполняется CLI на сервере CMS. Снимок содержит только страницы, не секреты.</p><form method="get"><input type="hidden" name="p" value="lite"><label>Проект<select name="project" required><?php selectOptions($projects,$pid) ?></select></label><button>Открыть</button></form></section>
<?php if($pid!==null): ?>
<section class="panel"><h2>Привязки сайтов</h2><ul><?php foreach($sites as $s): ?><li><a href="<?= h(url('lite',['project'=>$pid,'site'=>$s['id']])) ?>"><?= h($s['name']) ?></a> · <?= h($s['origin']) ?> · <?= (int)$s['active']?'активен':'отключён' ?></li><?php endforeach ?></ul>
<?php if($available): ?><form method="post"><?php formFields('lite.bind') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><label>Разрешённая цель<select name="target" required><?php selectOptions($available,null) ?></select></label><label>Название<input name="name" maxlength="120" required></label><button class="primary">Привязать (MFA)</button></form><?php endif ?>
<?php if($error): ?><p class="planning-warning"><?= h($error) ?></p><?php endif ?></section>
<?php if($site): $sid=(int)$site['id']; ?>
<section class="panel"><h2><?= h($site['name']) ?></h2><p><?= h($site['origin']) ?> · #<?= $sid ?> · Lite 1.6.0</p>
<?php if($user['role']==='owner'): ?><form method="post"><?php formFields('lite.toggle') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="site_id" value="<?= $sid ?>"><input type="hidden" name="active" value="<?= (int)$site['active']?0:1 ?>"><button><?= (int)$site['active']?'Отключить':'Включить' ?> (MFA)</button></form><?php endif ?>
<?php if(!$error): ?><p>Для обновления каталога оператор запускает <code>php bin/workspace lite:inspect <?= $sid ?> OWNER_ID</code>.</p><?php if($site['site_hash']): ?><p>Снимок: <?= h(gmdate('Y-m-d H:i:s',(int)$site['inspected_at'])) ?> UTC · SHA-256 <code><?= h($site['site_hash']) ?></code></p><?php else: ?><p>Нет актуального снимка. Сначала выполните inspect.</p><?php endif ?><?php endif ?></section>
<?php if(!$error&&$site['site_hash']): ?>
<section class="panel"><h2>Страницы сохранённого снимка</h2><?php foreach($catalog as $path=>$page): ?><details><summary><?= h($page['title']) ?> · <?= h($path) ?> · <?= $page['published']?'опубликована':'черновик' ?></summary><p>SHA-256 редакции <code><?= h($page['revision']) ?></code></p><pre class="release-text"><?= h($page['body']) ?></pre>
<?php if($manage&&!$page['published']&&preg_match('~\A/(?:[a-zA-Z0-9_-]+(?:/[a-zA-Z0-9_-]+)*)?\z~D',$path)): ?><form method="post"><?php formFields('lite.queue') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="site_id" value="<?= $sid ?>"><input type="hidden" name="site_hash" value="<?= h($site['site_hash']) ?>"><input type="hidden" name="kind" value="draft"><input type="hidden" name="path" value="<?= h($path) ?>"><button class="primary">Подтвердить публикацию черновика (MFA)</button></form><?php endif ?></details><?php endforeach ?></section>
<?php if($manage): ?><section class="panel"><h2>Выпустить страницу из Book</h2><p>Только новая страница. Markdown сохраняется как безопасный текст, без медиа и выполнения HTML.</p><?php if(!$editionOptions): ?><p>Нет согласованных подборок Book.</p><?php else: ?><form method="get"><input type="hidden" name="p" value="lite"><input type="hidden" name="project" value="<?= $pid ?>"><input type="hidden" name="site" value="<?= $sid ?>"><label>Согласованная подборка<select name="edition" required><option value="">Выберите</option><?php selectOptions($editionOptions,$editions[0]['id']??null) ?></select></label><button>Открыть подборку</button></form><?php endif ?>
<?php foreach($editions as $edition): $snap=json_decode($edition['snapshot'],true,64,JSON_THROW_ON_ERROR); ?><details><summary>#<?= (int)$edition['id'] ?> <?= h($edition['title']) ?> · <code><?= h($edition['snapshot_hash']) ?></code></summary><p><a href="<?= h(url('book',['project'=>$pid,'edition'=>$edition['id']])) ?>">Открыть согласованный снимок и рецензии</a></p>
<?php foreach($snap['pages'] as $entry): $page=$entry['page']; ?><article><h3><?= h($page['title']) ?></h3><p><?= h($entry['key']) ?> · <code><?= h($entry['sha256']) ?></code></p><?php if(!$page['media']&&strlen($page['body'])<=60000&&trim($page['body'])!==''): ?><pre class="release-text"><?= h($page['body']) ?></pre><form method="post"><?php formFields('lite.queue') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="site_id" value="<?= $sid ?>"><input type="hidden" name="site_hash" value="<?= h($site['site_hash']) ?>"><input type="hidden" name="kind" value="book"><input type="hidden" name="edition_id" value="<?= (int)$edition['id'] ?>"><input type="hidden" name="page_key" value="<?= h($entry['key']) ?>"><label>Новый путь<input name="path" placeholder="/docs/start" maxlength="1024" required></label><button class="primary">Подтвердить публикацию Book (MFA)</button></form><?php else: ?><p>Неподдерживаемый размер, пустой текст или медиа.</p><?php endif ?></article><?php endforeach ?></details><?php endforeach ?></section><?php endif ?><?php endif ?>
<?php if(!$error): ?><section class="panel"><h2>Журнал публикаций</h2><p>Последние 100 операций. Для прерванной записи используется сверка, не повторная публикация.</p><?php foreach($jobs as $j): $jid=(int)$j['id']; ?><article><h3>#<?= $jid ?> · <?= h($j['path']) ?> · <?= h($j['state']) ?></h3><p><?= h($j['kind']) ?> · автор #<?= (int)$j['actor_id'] ?> · <?= h(gmdate('Y-m-d H:i:s',(int)$j['updated_at'])) ?> UTC · <?= h($j['detail']) ?></p><p>Исходный SHA-256 <code><?= h($j['expected_hash']) ?></code><?php if($j['after_hash']): ?> · результат <code><?= h($j['after_hash']) ?></code><?php endif ?></p><?php if($j['edition_id']): ?><p><a href="<?= h(url('book',['project'=>$pid,'edition'=>$j['edition_id']])) ?>">Редакция Book #<?= (int)$j['edition_id'] ?></a></p><?php endif ?><?php if($j['backup_name']): ?><p>Резервная копия <code><?= h($j['backup_name']) ?></code> · <code><?= h($j['backup_hash']) ?></code></p><?php endif ?>
<?php if($j['state']==='queued'): ?><p><code>php bin/workspace lite:work <?= $jid ?></code></p><?php elseif($j['state']==='restore_queued'): ?><p>Остановите все процессы записи Lite: <code>php bin/workspace lite:restore <?= $jid ?> --offline</code></p><?php elseif(in_array($j['state'],['running','uncertain','restoring','restore_uncertain'],true)): ?><p><code>php bin/workspace lite:reconcile <?= $jid ?><?= in_array($j['state'],['restoring','restore_uncertain'],true)?' --offline':'' ?></code></p><?php elseif($j['state']==='published'): ?><p>Опубликованный путь на момент проверки: <a href="<?= h($site['origin'].$j['path']) ?>"><?= h($site['origin'].$j['path']) ?></a></p><?php endif ?>
<?php if($user['role']==='owner'&&in_array($j['state'],['queued','restore_queued','published'],true)): ?><form method="post"><?php formFields($j['state']==='published'?'lite.restore':'lite.cancel') ?><input type="hidden" name="project_id" value="<?= $pid ?>"><input type="hidden" name="site_id" value="<?= $sid ?>"><input type="hidden" name="job_id" value="<?= $jid ?>"><?php if($j['state']==='published'): ?><label><input type="checkbox" name="confirm" value="yes" required> Подтверждаю восстановление всего JSON сайта, только если он не менялся после этой публикации.</label><button>Запросить восстановление (MFA)</button><?php else: ?><button>Отменить ожидающую операцию (MFA)</button><?php endif ?></form><?php endif ?></article><?php endforeach ?></section><?php endif ?>
<?php endif ?><?php endif ?>
